BEGIN;
DO $$ DECLARE actor uuid;c uuid;client uuid;vendor uuid;j uuid;r uuid;q jsonb;blocked boolean;ls jsonb;BEGIN
SELECT p.id INTO actor FROM profiles p JOIN roles r ON r.id=p.role_id WHERE r.slug='super_admin' AND p.is_active LIMIT 1;
SELECT id INTO client FROM clients ORDER BY id LIMIT 1;
SELECT id INTO vendor FROM influencers WHERE tw_accounting_worked_vendor(id) ORDER BY id LIMIT 1;
IF client IS NULL OR vendor IS NULL THEN RAISE EXCEPTION 'Regression requires existing read-only directory identities';END IF;
PERFORM set_config('request.jwt.claim.sub',actor::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated','aal','aal2')::text,true);SET LOCAL ROLE authenticated;
c:=tw_accounting_create_company('QA hierarchy rollback '||gen_random_uuid(),'EG','EGP','2026-01-01','[{"code":"100000","name":"Assets","parent":null,"type":"Asset","normal":"Debit","kind":"Group"},{"code":"111001","name":"Bank","parent":"100000","type":"Asset","normal":"Debit","kind":"Posting"},{"code":"121001","name":"Receivables","parent":"100000","type":"Asset","normal":"Debit","kind":"Control","subledger":"Customer"},{"code":"200000","name":"Liabilities","parent":null,"type":"Liability","normal":"Credit","kind":"Group"},{"code":"211001","name":"Payables","parent":"200000","type":"Liability","normal":"Credit","kind":"Control","subledger":"Supplier / creator"},{"code":"221001","name":"Customer Advances","parent":"200000","type":"Liability","normal":"Credit","kind":"Control","subledger":"Customer"}]');
ls:=jsonb_build_array(jsonb_build_object('account','121001','clientId',client,'description','Customer AR','debit','100','credit','0'),jsonb_build_object('account','221001','clientId',client,'description','Same customer advance','debit','0','credit','100'));
j:=tw_accounting_save_signed_workflow(jsonb_build_object('id',gen_random_uuid(),'company',c,'date','2026-11-22','reference','HIERARCHY-QA','memo','Third Party across GL accounts','version',NULL,'lines',ls));
PERFORM tw_accounting_post_journal(j,c,1);
q:=tw_accounting_statement_filtered(c,'2026-01-01','2026-12-31',p_kind=>'client',p_party=>client);
IF jsonb_array_length(q->'accounts')<>2 OR jsonb_array_length(q->'auxiliaries')<>2 OR (SELECT sum((x->>'closing')::numeric) FROM jsonb_array_elements(q->'accounts') x)<>0 THEN RAISE EXCEPTION 'Party GL/consolidated balances incorrect';END IF;
IF EXISTS(SELECT 1 FROM jsonb_array_elements(q->'auxiliaries') x WHERE x->>'id'<>client::text OR x->>'name' IS NULL) THEN RAISE EXCEPTION 'Shared party identity lost';END IF;
q:=tw_accounting_statement_filtered(c,'2026-01-01','2026-12-31','121001','client',client);
IF (q->'accounts'->0->>'closing')::numeric<>100 THEN RAISE EXCEPTION 'Account-specific party statement incorrect';END IF;
r:=tw_accounting_reverse_journal(j,c,gen_random_uuid(),'2026-11-22','QA party reversal');
IF EXISTS(SELECT 1 FROM tw_accounting_journal_lines WHERE journal_id=r AND client_id IS DISTINCT FROM client) THEN RAISE EXCEPTION 'Reversal lost client';END IF;
ls:=jsonb_build_array(jsonb_build_object('account','111001','description','Bank','debit','100','credit','0'),jsonb_build_object('account','211001','vendorId',vendor,'description','Vendor liability','debit','0','credit','100'));
j:=tw_accounting_save_signed_workflow(jsonb_build_object('id',gen_random_uuid(),'company',c,'date','2026-11-22','reference','HIERARCHY-QA','memo','Vendor JV','version',NULL,'lines',ls));PERFORM tw_accounting_post_journal(j,c,1);
r:=tw_accounting_reverse_journal(j,c,gen_random_uuid(),'2026-11-22','QA vendor reversal');
IF NOT EXISTS(SELECT 1 FROM tw_accounting_journal_lines WHERE journal_id=r AND vendor_id=vendor) THEN RAISE EXCEPTION 'Reversal lost vendor';END IF;
ls:=jsonb_set(ls,'{1,vendorId}','null');blocked:=false;
BEGIN PERFORM tw_accounting_save_signed_workflow(jsonb_build_object('id',gen_random_uuid(),'company',c,'date','2026-11-22','reference','','memo','Missing party must fail','version',NULL,'lines',ls));EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%Third Party%' THEN RAISE;END IF;blocked:=true;END;
IF NOT blocked THEN RAISE EXCEPTION 'Missing party allowed';END IF;
ls:=jsonb_set(ls,'{1,account}','"200000"');blocked:=false;
BEGIN PERFORM tw_accounting_save_signed_workflow(jsonb_build_object('id',gen_random_uuid(),'company',c,'date','2026-11-22','reference','','memo','Main group must fail','version',NULL,'lines',ls));EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%GL account%' THEN RAISE;END IF;blocked:=true;END;
IF NOT blocked THEN RAISE EXCEPTION 'Main group allowed';END IF;
PERFORM tw_accounting_sync_directory(c);
IF EXISTS(SELECT 1 FROM tw_accounting_accounts WHERE company_id=c AND (client_id IS NOT NULL OR vendor_id IS NOT NULL)) THEN RAISE EXCEPTION 'Directory sync recreated person GL accounts';END IF;
RAISE NOTICE 'PASS: client/vendor JV, required detail, main-account rejection, per-GL and consolidated party balances, both reversals, sync creates no duplicate GLs';
END $$;
ROLLBACK;
